import numpy as np
from collections import deque
def comps(g):
    g=np.array(g); seen=np.zeros_like(g,bool); res=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i,j] and not seen[i,j]:
                col=g[i,j]; q=deque([(i,j)]); seen[i,j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<len(g) and 0<=b<len(g[0]) and not seen[a,b] and g[a,b]==col:
                            seen[a,b]=True; q.append((a,b))
                # flood whole component regardless of color within bbox
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                comp=set(cells); q2=deque(cell for cell in cells)
                while q2:
                    y,x=q2.popleft()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<len(g) and 0<=b<len(g[0]) and g[a,b]!=0 and (a,b) not in comp:
                            comp.add((a,b)); q2.append((a,b))
                h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
                res.append({'pos':cells,'h':h,'w':w})
    return res
